INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(7061340, 1074582, 112828, '<td valign="top">If you had actually lined yourself up with the church so it was balanced, this might have been a pretty good shot.</td>', 'If you had actually lined yourself up with the church so it was balanced, this might have been a pretty good shot.', '2013-07-06 01:18:29.000000', NULL, 1),
(7061341, 1074583, 112828, '<td valign="top">Very interesting perspective - I thought about doing this myself - looks cool!</td>', 'Very interesting perspective - I thought about doing this myself - looks cool!', '2013-07-06 01:19:04.000000', NULL, 1),
(7061345, 1074554, 112828, '<td valign="top">Hey, pretty cool!  Love the use of expert editing - although, you could have perhaps done a little better job with placement and masking.</td>', 'Hey, pretty cool!  Love the use of expert editing - although, you could have perhaps done a little better job with placement and masking.', '2013-07-06 01:22:30.000000', NULL, 1),
(7061346, 1074609, 112828, '<td valign="top">Very well done, at least in terms of concept and the fireworks.  The neckline is in that bad area of softness though - not soft enough to be good bokeh, but not sharp either.</td>', 'Very well done, at least in terms of concept and the fireworks.  The neckline is in that bad area of softness though - not soft enough to be good bokeh, but not sharp either.', '2013-07-06 01:23:31.000000', NULL, 1),
(7061351, 1074557, 112828, '<td valign="top">Hmm.  I like the texture and overall feel of this image very much.<br/> <br/>The one BIG problem for me is that crop line in the upper right corner of the nebula area.  That straight line just jars one much like the effect of being whacked upside the head with a shovel while in the middle of enjoying a rather delicious ice cream.  Shame though, lovely image otherwise.</td>', 'Hmm.  I like the texture and overall feel of this image very much. The one BIG problem for me is that crop line in the upper right corner of the nebula area.  That straight line just jars one much like the effect of being whacked upside the head with a shovel while in the middle of enjoying a rather delicious ice cream.  Shame though, lovely image otherwise.', '2013-07-06 01:36:22.000000', NULL, 1),
(7061353, 1074581, 112828, '<td valign="top">Hail to the Red, White, and Blue.</td>', 'Hail to the Red, White, and Blue.', '2013-07-06 01:38:02.000000', NULL, 1),
(7061359, 1074597, 112828, '<td valign="top">Hmm.  Lens flare shockwave! ;)<br/> <br/>Points for creativity.</td>', 'Hmm.  Lens flare shockwave! ;) Points for creativity.', '2013-07-06 01:42:54.000000', NULL, 1),
(7061360, 1074611, 112828, '<td valign="top">C/O?<br/> <br/>Fun image in any case.</td>', 'C/O? Fun image in any case.', '2013-07-06 01:43:12.000000', NULL, 1),
(7061362, 1074613, 112828, '<td valign="top">That flagpole and the garage/building are totally in the way.<br/> <br/>The St. Louis Arch is a great inclusion though.<br/> <br/>FYI - dodging/burning the edges of images that have really super bright areas is silly - it always looks bad.</td>', 'That flagpole and the garage/building are totally in the way. The St. Louis Arch is a great inclusion though. FYI - dodging/burning the edges of images that have really super bright areas is silly - it always looks bad.', '2013-07-06 01:45:55.000000', NULL, 1),
(7061365, 1074575, 112828, '<td valign="top">Not bad, but there is some noise in the red channel in the sky.<br/> <br/>With the expert rules available, at least an HDR image would have been advisable. (legal in Advanced even)  That way the city could have been more properly illuminated, and the fireworks would still have remained spectacular!<br/> <br/>...<br/> <br/>Overall though, not bad at all.</td>', 'Not bad, but there is some noise in the red channel in the sky. With the expert rules available, at least an HDR image would have been advisable. (legal in Advanced even)  That way the city could have been more properly illuminated, and the fireworks would still have remained spectacular! ... Overall though, not bad at all.', '2013-07-06 01:51:55.000000', NULL, 1),
(7061366, 1074610, 112828, '<td valign="top">The colors here are strangely more saturated in the water than in the fireworks.</td>', 'The colors here are strangely more saturated in the water than in the fireworks.', '2013-07-06 01:52:21.000000', NULL, 1),
(7061367, 1074605, 112828, '<td valign="top">A reasonable compilation, but there are a few points of distraction, such as the rather sparse and OOF red firework.</td>', 'A reasonable compilation, but there are a few points of distraction, such as the rather sparse and OOF red firework.', '2013-07-06 01:53:04.000000', NULL, 1),
(7061373, 1074602, 112828, '<td valign="top">A bit of flash in the foreground would have been nice, but overall this is a pretty solid image, with nice balance and good processing overall.</td>', 'A bit of flash in the foreground would have been nice, but overall this is a pretty solid image, with nice balance and good processing overall.', '2013-07-06 02:14:32.000000', NULL, 1),
(7061375, 1074552, 112828, '<td valign="top">Nice image.<br/> <br/>I think maybe you shot this at a somewhat narrow aperture to give that wonderful starburst at the end of each trail?<br/> <br/>The issue I have with this image is all attention to details - there is a red blob at the right hand edge (sensor heat/noise on a Nikon maybe?) and there is a puff of smoke in the trails at the bottom that is pretty darn distracting.</td>', 'Nice image. I think maybe you shot this at a somewhat narrow aperture to give that wonderful starburst at the end of each trail? The issue I have with this image is all attention to details - there is a red blob at the right hand edge (sensor heat/noise on a Nikon maybe?) and there is a puff of smoke in the trails at the bottom that is pretty darn distracting.', '2013-07-06 02:16:40.000000', NULL, 1),
(7061376, 1074612, 112828, '<td valign="top">Powerful use of negative space.  Very nicely done.</td>', 'Powerful use of negative space.  Very nicely done.', '2013-07-06 02:16:58.000000', NULL, 1),
(7061379, 1074555, 112828, '<td valign="top">Hmm.  Looks like a self portrait to me.  Maybe I can imagine that what looks like light shining through leaves is instead fireworks.<br/> <br/>Not vague enough to make me enjoy it, and certainly not on topic enough to make me think ''Fireworks'' when I view it.  <br/> <br/>More blur please. ;)</td>', 'Hmm.  Looks like a self portrait to me.  Maybe I can imagine that what looks like light shining through leaves is instead fireworks. Not vague enough to make me enjoy it, and certainly not on topic enough to make me think ''Fireworks'' when I view it.   More blur please. ;)', '2013-07-06 02:22:03.000000', NULL, 1),
(7061381, 1074556, 112828, '<td valign="top">I don''t care for the wonky effect that the rotation produces.  Looks unnatural.</td>', 'I don''t care for the wonky effect that the rotation produces.  Looks unnatural.', '2013-07-06 02:23:37.000000', NULL, 1),
(7061382, 1074578, 112828, '<td valign="top">The fireworks look great.  Too bad the foreground/city looks so bad in terms of processing.  Just over-processed looking in general.<br/> <br/>Next time, mask each separate from the other, and process independently.<br/> <br/>Also a big issue is the firework bust in the building at the left hand side of the image.  That''s really really really distracting.<br/> <br/>Overall though, I do have to say that the general composition is pretty strong, and with a bit more care in the processing, this could have been pretty stellar.</td>', 'The fireworks look great.  Too bad the foreground/city looks so bad in terms of processing.  Just over-processed looking in general. Next time, mask each separate from the other, and process independently. Also a big issue is the firework bust in the building at the left hand side of the image.  That''s really really really distracting. Overall though, I do have to say that the general composition is pretty strong, and with a bit more care in the processing, this could have been pretty stellar.', '2013-07-06 02:24:13.000000', NULL, 1),
(7061383, 1074579, 112828, '<td valign="top">Cool, looks like an eyeball with reflections of fireworks.  I like the abstract, and think it''s ok for this challenge too! <br/> <br/>:D<br/> <br/>The dirt spots really help.</td>', 'Cool, looks like an eyeball with reflections of fireworks.  I like the abstract, and think it''s ok for this challenge too!  :D The dirt spots really help.', '2013-07-06 02:24:54.000000', NULL, 1),
(7061384, 1074576, 112828, '<td valign="top">The fireworks are pretty ok, but... the top is missing, and there seems to be either a killer clown, or a jellyfish of some sort, at the <strike>right</strike>  left edge of the image - either way, I don''t see how it relates to the fireworks. ;)<br/><br/><i>Message edited by author 2013-07-13 01:10:34.</i></td>', 'The fireworks are pretty ok, but... the top is missing, and there seems to be either a killer clown, or a jellyfish of some sort, at the right  left edge of the image - either way, I don''t see how it relates to the fireworks. ;)', '2013-07-06 02:25:33.000000', '2013-07-13 02:10:34.000000', 1),
(7061385, 1074539, 112828, '<td valign="top">Hmm.. Too much going on, and there''s some sort of building or reflection in the lower right corner which is distracting.</td>', 'Hmm.. Too much going on, and there''s some sort of building or reflection in the lower right corner which is distracting.', '2013-07-06 02:25:35.000000', NULL, 1),
(7061386, 1074607, 112828, '<td valign="top">This image is only 96KB, and it shows in the details - there are compression artifacts, and just generally a kinda messy appearance to the image.<br/> <br/>Shame though, as it''s really otherwise a rather good capture (other than being cut off) using a challenging technique.</td>', 'This image is only 96KB, and it shows in the details - there are compression artifacts, and just generally a kinda messy appearance to the image. Shame though, as it''s really otherwise a rather good capture (other than being cut off) using a challenging technique.', '2013-07-06 02:25:50.000000', NULL, 1),
(7061387, 1074591, 112828, '<td valign="top">Trying for brown, or just too much in a hurry to actually name the image?<br/> <br/>The grain is pretty bad, but not as bad as the composition - not sure why we''re seeing trucks and cars, but if you had cropped this to include less distracting elements, I''m sure it would have found more love.<br/> <br/>Fireworks do look pretty good though, nice timing, and nice color/sharpness.</td>', 'Trying for brown, or just too much in a hurry to actually name the image? The grain is pretty bad, but not as bad as the composition - not sure why we''re seeing trucks and cars, but if you had cropped this to include less distracting elements, I''m sure it would have found more love. Fireworks do look pretty good though, nice timing, and nice color/sharpness.', '2013-07-06 02:25:53.000000', NULL, 1),
(7061388, 1074596, 112828, '<td valign="top">A fairly well executed version of this type of image at first glance, however after inspecting this for a few minutes, I''m afraid that I''ve found it wanting in several respects.<br/> <br/>The bursts have been rotated, leaving the effects of gravity all messed up.<br/> <br/>As a result, the physics of this image are distracting to my eye, and it does diminish the enjoyment for me somewhat.<br/> <br/>There is also a degree of varying sharpness here, and that is somewhat distracting as well.<br/> <br/>Still, not a bad job, you certainly did create an image that most will, at first glance, find quite pleasing.</td>', 'A fairly well executed version of this type of image at first glance, however after inspecting this for a few minutes, I''m afraid that I''ve found it wanting in several respects. The bursts have been rotated, leaving the effects of gravity all messed up. As a result, the physics of this image are distracting to my eye, and it does diminish the enjoyment for me somewhat. There is also a degree of varying sharpness here, and that is somewhat distracting as well. Still, not a bad job, you certainly did create an image that most will, at first glance, find quite pleasing.', '2013-07-06 02:25:58.000000', NULL, 1),
(7061389, 1074551, 112828, '<td valign="top">Cool.  I think you did a great job conceptually, but you killed this with processing - the edges of the bursts look like you''ve used ''wet edges'' with the paintbrush tool to create them.<br/> <br/>Really too bad, because I think the yellow/red/white burst is just astonishingly beautiful.</td>', 'Cool.  I think you did a great job conceptually, but you killed this with processing - the edges of the bursts look like you''ve used ''wet edges'' with the paintbrush tool to create them. Really too bad, because I think the yellow/red/white burst is just astonishingly beautiful.', '2013-07-06 02:26:06.000000', NULL, 1),
(7061390, 1074601, 112828, '<td valign="top">A Taylor Swift tour shirt huh?  Man.  Between that, the massive noise, the fact that 1/3 of the image is pretty uninteresting and the ''chunky'' look to the fireworks, I''m really torn as to how to score what is otherwise a pretty good image of fireworks, which were reasonably well shot and picked.<br/> <br/>Hmmm...  Dang, hard one.  I''ll have to think about this one for a while.</td>', 'A Taylor Swift tour shirt huh?  Man.  Between that, the massive noise, the fact that 1/3 of the image is pretty uninteresting and the ''chunky'' look to the fireworks, I''m really torn as to how to score what is otherwise a pretty good image of fireworks, which were reasonably well shot and picked. Hmmm...  Dang, hard one.  I''ll have to think about this one for a while.', '2013-07-06 02:26:13.000000', NULL, 1),
(7061391, 1074595, 112828, '<td valign="top">I don''t like this... <br/> <br/>But the fireworks are well shot, and look good.  I''m not sure what to do with this one.</td>', 'I don''t like this...  But the fireworks are well shot, and look good.  I''m not sure what to do with this one.', '2013-07-06 02:26:16.000000', NULL, 1),
(7061392, 1074606, 112828, '<td valign="top">LOL!  This is a fun one.  <br/> <br/>Crappy framing, and there''s a few other problems here, but you captured a great moment here. <br/> <br/>I think that a tighter crop would have been wise here.</td>', 'LOL!  This is a fun one.   Crappy framing, and there''s a few other problems here, but you captured a great moment here.  I think that a tighter crop would have been wise here.', '2013-07-06 02:26:20.000000', NULL, 1),
(7061393, 1074536, 112828, '<td valign="top">You may want to get screened for Parkinson''s, or at least cut back on the caffeinated drinks. ;)<br/> <br/>Really though, in seriousness, this is a pretty good image, the delicate nature of the lines is attractive, as is the color palate.</td>', 'You may want to get screened for Parkinson''s, or at least cut back on the caffeinated drinks. ;) Really though, in seriousness, this is a pretty good image, the delicate nature of the lines is attractive, as is the color palate.', '2013-07-06 02:26:27.000000', NULL, 1),
(7061394, 1074586, 112828, '<td valign="top">Hmm.  This isn''t too bad,  I do rather like the overall effect, and I think the smoke adds something here, which is a nice change from the usual distracting effect the smoke has.</td>', 'Hmm.  This isn''t too bad,  I do rather like the overall effect, and I think the smoke adds something here, which is a nice change from the usual distracting effect the smoke has.', '2013-07-06 02:26:32.000000', NULL, 1),
(7061395, 1074558, 112828, '<td valign="top">Since this was expert, very silly of you to do that top border thing, and not just clone in some sky...<br/> <br/>Still, one of the better images in the challenge IMO.</td>', 'Since this was expert, very silly of you to do that top border thing, and not just clone in some sky... Still, one of the better images in the challenge IMO.', '2013-07-06 02:27:25.000000', NULL, 1),
(7061396, 1074584, 112828, '<td valign="top">A fun mess. :)<br/> <br/>Really though, the black isn''t black, and the fireworks are somewhat blurry.</td>', 'A fun mess. :) Really though, the black isn''t black, and the fireworks are somewhat blurry.', '2013-07-06 02:27:39.000000', NULL, 1),
(7061397, 1074571, 112828, '<td valign="top">Interesting details, but to my eyes, a longer shutter speed always works better with fireworks.</td>', 'Interesting details, but to my eyes, a longer shutter speed always works better with fireworks.', '2013-07-06 02:27:49.000000', NULL, 1),
(7061399, 1074604, 112828, '<td valign="top">Good processing and color.  I think the foreground is ok at best, but certainly not terrible, and it''s fun to see all those people lined up!</td>', 'Good processing and color.  I think the foreground is ok at best, but certainly not terrible, and it''s fun to see all those people lined up!', '2013-07-06 02:28:05.000000', NULL, 1),
(7061440, 1074558, 16046, '<td valign="top">Best in show award, congrats</td>', 'Best in show award, congrats', '2013-07-06 10:10:03.000000', NULL, 1),
(7061457, 1074536, 121111, '<td valign="top">wonderful sharpness and compositions</td>', 'wonderful sharpness and compositions', '2013-07-06 10:27:20.000000', NULL, 1),
(7061460, 1074557, 121111, '<td valign="top">wow ! you also got the stars ... nice job !</td>', 'wow ! you also got the stars ... nice job !', '2013-07-06 10:28:16.000000', NULL, 1),
