(7061467, 1074602, 121111, '<td valign="top">:) nice detail including the crowd relaxing</td>', ':) nice detail including the crowd relaxing', '2013-07-06 10:30:32.000000', NULL, 1),
(7061469, 1074603, 121111, '<td valign="top">intense it is!</td>', 'intense it is!', '2013-07-06 10:31:35.000000', NULL, 1),
