(7061512, 1074575, 114225, '<td valign="top">Cool that you can see a bit of a bridge, it works well with the curves of the sparks.</td>', 'Cool that you can see a bit of a bridge, it works well with the curves of the sparks.', '2013-07-06 11:35:08.000000', NULL, 1),
(7061516, 1074586, 114225, '<td valign="top">Wow, a lot going on here. Not sure where to pay attention to.</td>', 'Wow, a lot going on here. Not sure where to pay attention to.', '2013-07-06 11:36:08.000000', NULL, 1),
(7061522, 1074603, 114225, '<td valign="top">Very nice display. I like the colors quite a bit.</td>', 'Very nice display. I like the colors quite a bit.', '2013-07-06 11:39:41.000000', NULL, 1),
(7061523, 1074604, 114225, '<td valign="top">Ooh, nice color transition.</td>', 'Ooh, nice color transition.', '2013-07-06 11:40:14.000000', NULL, 1),
(7061526, 1074613, 114225, '<td valign="top">Oh, it''s a flag obstructing the view. I get the patriotism, but I think this would get another point higher from me if it wasn''t there.</td>', 'Oh, it''s a flag obstructing the view. I get the patriotism, but I think this would get another point higher from me if it wasn''t there.', '2013-07-06 11:42:12.000000', NULL, 1),
(7061528, 1074583, 114225, '<td valign="top">Small town? Not with that many lights and blasts :)</td>', 'Small town? Not with that many lights and blasts :)', '2013-07-06 11:42:59.000000', NULL, 1),
(7061529, 1074609, 114225, '<td valign="top">Very cute idea!</td>', 'Very cute idea!', '2013-07-06 11:43:27.000000', NULL, 1),
(7061531, 1074536, 114225, '<td valign="top">Nice job adding a touch of creativity.</td>', 'Nice job adding a touch of creativity.', '2013-07-06 11:44:15.000000', NULL, 1),
(7061532, 1074601, 114225, '<td valign="top">With a Taylor swift tour shirt. Classic.</td>', 'With a Taylor swift tour shirt. Classic.', '2013-07-06 11:44:51.000000', NULL, 1),
(7061534, 1074596, 114225, '<td valign="top">A lot of beauty to look at.<br/>Funny how some of the blasts appear to be curving UP.</td>', 'A lot of beauty to look at.Funny how some of the blasts appear to be curving UP.', '2013-07-06 11:46:01.000000', NULL, 1),
(7061538, 1074558, 114225, '<td valign="top">Those flat blasts are a lot of fun to capture. Well done.</td>', 'Those flat blasts are a lot of fun to capture. Well done.', '2013-07-06 11:47:31.000000', NULL, 1),
(7061539, 1074552, 114225, '<td valign="top">Oh cool. Looks like stars in the sky.</td>', 'Oh cool. Looks like stars in the sky.', '2013-07-06 11:48:08.000000', NULL, 1),
(7061541, 1074576, 114225, '<td valign="top">Ha, I caught a face in the booms this year too.</td>', 'Ha, I caught a face in the booms this year too.', '2013-07-06 11:50:15.000000', NULL, 1),
(7061542, 1074556, 114225, '<td valign="top">Love the sweeping action, and the rainbow of colors.</td>', 'Love the sweeping action, and the rainbow of colors.', '2013-07-06 11:51:18.000000', NULL, 1),
