(7061546, 1074540, 114225, '<td valign="top">Well composed.</td>', 'Well composed.', '2013-07-06 11:53:32.000000', NULL, 1),
(7061547, 1074578, 114225, '<td valign="top">Nicely framed display.</td>', 'Nicely framed display.', '2013-07-06 11:56:19.000000', NULL, 1),
(7061548, 1074554, 114225, '<td valign="top">Behold the power. Well done.</td>', 'Behold the power. Well done.', '2013-07-06 11:56:45.000000', NULL, 1),
(7061549, 1074602, 114225, '<td valign="top">A classic view, with a rather unamused onlooker.</td>', 'A classic view, with a rather unamused onlooker.', '2013-07-06 11:57:15.000000', NULL, 1),
(7061550, 1074607, 114225, '<td valign="top">Yes, the out of focus technique sure brings a new level to fireworks.</td>', 'Yes, the out of focus technique sure brings a new level to fireworks.', '2013-07-06 11:58:01.000000', NULL, 1),
(7061551, 1074595, 114225, '<td valign="top">At first I though this was the Millennium Falcon.</td>', 'At first I though this was the Millennium Falcon.', '2013-07-06 11:58:35.000000', NULL, 1),
(7061552, 1074557, 114225, '<td valign="top">That''s a really cool idea. Cool enough that I may have to steal it.</td>', 'That''s a really cool idea. Cool enough that I may have to steal it.', '2013-07-06 11:59:05.000000', NULL, 1),
(7061553, 1074571, 114225, '<td valign="top">Well, I wasn''t expecting monochrome!</td>', 'Well, I wasn''t expecting monochrome!', '2013-07-06 11:59:29.000000', NULL, 1),
(7061575, 1074609, 24546, '<td valign="top">Very creative and well done!</td>', 'Very creative and well done!', '2013-07-06 12:44:54.000000', NULL, 1),
(7061576, 1074554, 24546, '<td valign="top">Well done.</td>', 'Well done.', '2013-07-06 12:45:27.000000', NULL, 1),
(7061581, 1074602, 24546, '<td valign="top">Love the the capture  of the whole scene - the people watching the fireworks, the location, as well as the fireworks themselves. Great job!</td>', 'Love the the capture  of the whole scene - the people watching the fireworks, the location, as well as the fireworks themselves. Great job!', '2013-07-06 12:48:28.000000', NULL, 1),
(7061583, 1074579, 24546, '<td valign="top">Out of focus such that I can''t tell what you have photographed.</td>', 'Out of focus such that I can''t tell what you have photographed.', '2013-07-06 12:49:52.000000', NULL, 1),
(7061602, 1074596, 164773, '<td valign="top">Nicely done.  Not overexposed.</td>', 'Nicely done.  Not overexposed.', '2013-07-06 14:42:14.000000', NULL, 1),
